$out = "-- Expanded field-service reference library. Review drafts before publication.\nSET NAMES utf8mb4;\nSTART TRANSACTION;\nSET @author_id = (SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE u.status='active' AND u.deleted_at IS NULL AND r.name IN ('Admin','Super Admin') ORDER BY u.id LIMIT 1);\n";
$counts = [];
function literal($value) {
    if ($value === null) return 'NULL';
    if (is_int($value)) return (string)$value;
    if (strpos($value, '\\') !== false) return "CONVERT(0x".bin2hex($value)." USING utf8mb4)";
    return "'".str_replace("'", "''", $value)."'";
}
function addRow($table, $data, $key, $from = '', $condition = '') {
    global $out, $counts;
    $values = array_map('literal', array_values($data));
    if ($table === 'knowledge_articles') $values[array_search('author_id', array_keys($data))] = '@author_id';
    if ($table === 'commands') $values[0] = 'c.id';
    $where = "NOT EXISTS (SELECT 1 FROM `$table` WHERE `$key`=".literal($data[$key]).")";
    if ($condition) $where = $condition.' AND '.$where;
    $out .= "\nINSERT INTO `$table` (`".implode('`,`', array_keys($data))."`)\nSELECT ".implode(',', $values).($from ? ' FROM '.$from : '')." WHERE $where;\n";
    $counts[$table] = ($counts[$table] ?? 0) + 1;
}
