foreach ($commands as $c) {
    [$slug,$command,$description,$when,$example,$expected,$risk,$ps] = $c;
    $url=$ms;
    if ($ps) {
        $module = in_array($command,['Get-WinEvent'],true) ? 'microsoft.powershell.diagnostics' : (in_array($command,['Get-Process','Get-Service'],true) ? 'microsoft.powershell.management' : null);
        if (!$module && in_array($command,['Get-NetIPConfiguration','Get-NetRoute'],true)) $module='nettcpip';
        if (!$module && $command==='Resolve-DnsName') $module='dnsclient';
        if (!$module && in_array($command,['Get-Volume','Get-Disk','Get-PhysicalDisk'],true)) $module='storage';
        if (!$module && in_array($command,['Get-Printer','Get-PrintJob'],true)) $module='printmanagement';
        if (!$module && strpos($command,'Get-CimInstance')===0) $module='cimcmdlets';
        if ($module) $url='https://learn.microsoft.com/en-us/powershell/module/'.$module.'/'.strtolower(explode(' ',$command)[0]);
    }
    addRow('commands',['category_id'=>0,'command'=>$command,'description'=>$description,'when_to_use'=>$when,'example'=>$example,'expected_output'=>$expected,'common_errors'=>'Check elevation, module availability, exact target and OS support. Do not infer hardware failure from one unsuccessful command.','next_steps'=>'Save relevant output with sensitive details redacted, then follow the next evidence-based diagnostic. Reference: '.$url,'risk_level'=>$risk,'is_powershell'=>$ps],'command','command_categories c',"c.slug=".literal($slug));
}
